typedef float rational_t;
typedef unsigned long uint64;

class pstring
{
  uint64 pchunk[4];
  void pack_string(const char *);
public:
  pstring(const char *target_string)
  {
    pack_string(target_string);
  }

  bool operator==(const pstring &check_me) const
  {
    for (unsigned i=0; i<4; ++i)
    {
      if (pchunk[i] != check_me.pchunk[i])
        return false;
    }
    return true;
  }
};

class entity;

class generic_interface
{
public:
  virtual ~generic_interface();
};

class entity_interface : public generic_interface
{
protected:
  entity *my_entity;
};

class ai_interface : public entity_interface
{
protected:
  unsigned int flags;

public:
  enum
  {
    _AI_ACTIVE = 0x00000001,
    _AI_REACHED_DEST = 0x00000040,
    _AI_COSMETIC = 0x00000080
  };

  inline bool is_flagged(unsigned int f) const
  {
    return((flags & f) != 0);
  }

  inline bool is_active() const
  {
    return(is_flagged(_AI_ACTIVE) && my_entity != 0);
  }

  inline bool reached_dest() const
  {
    return(is_flagged(_AI_REACHED_DEST));
  }

  inline bool cosmetic() const
  {
    return(is_flagged(_AI_COSMETIC));
  }

  bool get_ifc_num(const pstring &att, rational_t &val);
};

#define IFC_INTERNAL_GET_MACRO(a,b) { static pstring pstring_get(a); if(att == pstring_get) { val = b; return(true); } }
#define IFC_INTERNAL_FUNC_MACRO(a,b) { static pstring pstring_func(a); if(att == pstring_func) { b; return(true); } }

bool ai_interface::get_ifc_num(const pstring &att, rational_t &val)
{
  IFC_INTERNAL_FUNC_MACRO("AI_ACTIVE", is_active());
  IFC_INTERNAL_FUNC_MACRO("AI_COSMETIC", cosmetic());
#if 0 // BIGCULL
  IFC_INTERNAL_GET_MACRO("AI_EYE_ARC", eyes->detection_arc);
  IFC_INTERNAL_GET_MACRO("AI_EYE_ARC_Y", eyes->detection_arc_y);
  IFC_INTERNAL_GET_MACRO("AI_EYE_MIN", eyes->min_dist);
  IFC_INTERNAL_GET_MACRO("AI_EYE_MAX", eyes->max_dist);
  IFC_INTERNAL_GET_MACRO("AI_EAR_ARC", ears->detection_arc);
  IFC_INTERNAL_GET_MACRO("AI_EAR_MIN", ears->min_dist);
  IFC_INTERNAL_GET_MACRO("AI_EAR_MAX", ears->max_dist);
#endif // BIGCULL
  IFC_INTERNAL_GET_MACRO("AI_REACHED_DEST", reached_dest());

  return(false);
}
